<?php
$pageTitle='Order | Moleqra';require_once __DIR__.'/includes/bootstrap.php';require_once __DIR__.'/includes/commerce.php';require_once __DIR__.'/includes/invoices.php';require_once __DIR__.'/includes/refunds.php';$pdo=db();$token=(string)($_GET['token']??'');$order=$pdo&&commerce_schema_ready($pdo)?commerce_order_by_token($pdo,$token):null;$invoice=null;$refunds=[];if($order){$pageTitle=$order['order_number'].' | Moleqra';if(invoice_schema_ready($pdo))$invoice=invoice_for_order($pdo,(int)$order['id']);if(refunds_schema_ready($pdo)){$s=$pdo->prepare("SELECT * FROM order_refunds WHERE order_id=:id AND status='Processed' ORDER BY processed_at DESC");$s->execute(['id'=>$order['id']]);$refunds=$s->fetchAll();}}else http_response_code(404);require __DIR__.'/includes/header.php';?>
<section class="page-hero"><div class="container"><div class="eyebrow">Order status</div><h1><?= e($order['order_number']??'Order not found') ?></h1><?php if($order):?><p><?= e($order['status']) ?> · Payment <?= e($order['payment_status']) ?> · <?= e($order['fulfilment_status']) ?></p><?php endif;?></div></section>
<section class="section"><div class="container"><?php if(!$order):?><div class="card">This order link is invalid or unavailable.</div><?php else:?><div class="grid-2"><section class="card"><h2>Items</h2><?php foreach($order['items'] as $i):?><p class="order-line"><span><?= e($i['product_name'].(!empty($i['variant_label'])?' · '.$i['variant_label']:'')) ?> × <?= e((string)$i['quantity']) ?></span><strong><?= e($order['currency']) ?> <?= number_format((float)$i['line_total'],2) ?></strong></p><?php endforeach;?><hr><p class="order-line"><span>Shipping</span><strong><?= e($order['currency']) ?> <?= number_format((float)$order['shipping_total'],2) ?></strong></p><p class="checkout-total"><span>Total</span><strong><?= e($order['currency']) ?> <?= number_format((float)$order['grand_total'],2) ?></strong></p><?php if($invoice):?><a class="btn" href="invoice.php?token=<?= e($order['order_token']) ?>">Invoice <?= e($invoice['invoice_number']) ?></a><?php endif;?></section><section class="card"><h2>Delivery</h2><p><?= e($order['first_name'].' '.$order['last_name']) ?><br><?= e($order['company']) ?><br><?= e($order['address_line1']) ?><?= $order['address_line2']?'<br>'.e($order['address_line2']):'' ?><br><?= e($order['city'].', '.$order['province'].' '.$order['postal_code']) ?></p><?php if(!empty($order['shipments'])):$sh=$order['shipments'][0];?><p><strong>Shipment</strong><br><?= e($sh['courier']?:'Courier') ?><?= $sh['service']?' · '.e($sh['service']):'' ?><?php if($sh['tracking_number']):?><br>Tracking: <?= e($sh['tracking_number']) ?><?php endif;?></p><?php endif;?><?php if($order['payment_status']==='Pending'):?><a class="btn primary" href="payment/payfast-start.php?token=<?= e($order['order_token']) ?>">Continue payment</a><?php endif;?><?php if($refunds):?><h3>Refunds</h3><?php foreach($refunds as $r):?><p><?= e($r['refund_number']) ?> · <?= e($r['currency']) ?> <?= number_format((float)$r['amount'],2) ?><br><a href="refund-receipt.php?token=<?= e($order['order_token']) ?>&refund=<?= (int)$r['id'] ?>">Refund receipt</a></p><?php endforeach;?><?php endif;?></section></div><?php endif;?></div></section>
